// Collegamento del conto a Enable Banking (da eseguire a mano, una tantum o alla scadenza del consenso).
// Campo 'codice' nel nodo Parametri:
//   - 'banche'  -> elenca le banche italiane che corrispondono a EB_ASPSP_NAME (per trovare il nome esatto)
//   - vuoto     -> passo 1: genera il link di autorizzazione
//   - <codice>  -> passo 2: crea la sessione e restituisce session_id da mettere in EB_SESSION_ID
const crypto = require('crypto');
const API = 'https://api.enablebanking.com';
const b64 = (v) => Buffer.from(typeof v === 'string' ? v : JSON.stringify(v)).toString('base64url');
const now = Math.floor(Date.now() / 1000);
const unsigned = b64({ typ: 'JWT', alg: 'RS256', kid: $env.EB_APP_ID }) + '.' +
  b64({ iss: 'enablebanking.com', aud: 'api.enablebanking.com', iat: now, exp: now + 3600 });
const key = String($env.EB_PRIVATE_KEY || '').replace(/\\n/g, '\n');
const jwt = unsigned + '.' + crypto.createSign('RSA-SHA256').update(unsigned).sign(key).toString('base64url');
const headers = { Authorization: 'Bearer ' + jwt };
const country = $env.EB_ASPSP_COUNTRY || 'IT';
const input = String($input.first().json.codice || '').trim();

if (input === 'banche') {
  const res = await this.helpers.httpRequest({ method: 'GET', url: API + '/aspsps', qs: { country }, headers, json: true });
  const q = String($env.EB_ASPSP_NAME || 'bpm').toLowerCase();
  const banche = (res.aspsps || []).map((a) => a.name).filter((n) => n.toLowerCase().includes(q) || /webank|bpm/i.test(n));
  return [{ json: { banche } }];
}

if (!input) {
  const validUntil = new Date(Date.now() + Number($env.EB_CONSENT_DAYS || 180) * 86400000).toISOString();
  const res = await this.helpers.httpRequest({
    method: 'POST', url: API + '/auth', headers, json: true,
    body: {
      access: { valid_until: validUntil },
      aspsp: { name: $env.EB_ASPSP_NAME, country },
      state: crypto.randomUUID(),
      redirect_url: $env.EB_REDIRECT_URL,
      psu_type: 'personal',
    },
  });
  return [{ json: { passo: '1/2', istruzioni: "Apri l'url, autorizza dall'app della banca, poi copia il parametro 'code' dall'indirizzo di ritorno nel campo 'codice' del nodo Parametri e riesegui.", url: res.url } }];
}

const s = await this.helpers.httpRequest({ method: 'POST', url: API + '/sessions', headers, json: true, body: { code: input } });
return [{ json: { passo: '2/2', istruzioni: 'Copia session_id in EB_SESSION_ID nel file .env, svuota il campo codice e riavvia n8n.', session_id: s.session_id, accounts: s.accounts, access: s.access } }];
